package main

import (
	"encoding/json"
	"fmt"
	"net/http"
)

// Define the Todo resource
type Todo struct {
	Title    string `json:"title"`
	Completed bool   `json:"completed"`
}

// AddTodoHandler returns the HTTP response when a GET request is made to /todos
func (r *http.Request) http.HandlerFunc(w http.ResponseWriter, r *http.Request) {
	// Get all todos
	todos := findAllTodos()

	// Serialize the todos as JSON and send it to the client
	response := struct {
		Todos []Todo `json:"todos"`
	}{
		todos,
	}

	j, err := json.Marshal(response)
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Write(j)
}

// findAllTodos retrieves all todos and returns them as a slice
func findAllTodos() []Todo {
	// Simulate fetching todos from an external source
	return []Todo{
		Todo{Title: "Learn Go", Completed: true},
		Todo{Title: "Read a book", Completed: false},
	}
}

func main() {
	http.ListenAndServe(":8080", nil)
}

