package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"

	"github.com/google/uuid"
)

type Todo struct {
	ID        uuid.UUID `json:"id"`
	Title   string  `json:"title"`
	Completed bool    `json:"completed"`
}

var todos = []Todo{}

func listTodos(w http.ResponseWriter, r *http.Request) {
	t := make([]map[string]interface{}, len(todos))
	for i, todo := range todos {
		t[i] = map[string]interface{}{
			"ID":        fmt.Sprintf("%s", todo.ID),
			"Title":   todo.Title,
			"Completed": todo.Completed,
		}
	}

	err := json.NewEncoder(w).Encode(t)
	if err != nil {
		http.Error(w, fmt.Sprintf("Error encoding todos: %s", err), http.StatusInternalServerError)
	}
}

func getTodoByID(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	idStr := vars["id"]

	id, err := uuid.Parse(idStr)
	if err != nil {
		http.Error(w, fmt.Sprintf("Invalid ID: %s", err), http.StatusBadRequest)
		return
	}

	for _, todo := range todos {
		if todo.ID == id {
			t := map[string]interface{}{
				"ID":        fmt.Sprintf("%s", todo.ID),
				"Title":   todo.Title,
				"Completed": todo.Completed,
			}
			err := json.NewEncoder(w).Encode(t)
			if err != nil {
				http.Error(w, fmt.Sprintf("Error encoding todos: %s", err), http.StatusInternalServerError)
			}
			return
		}
	}

	http.Error(w, "Todo not found", http.StatusNotFound)
}

func createTodo(w http.ResponseWriter, r *http.Request) {
	var newTodo Todo
	err := json.NewDecoder(r.Body).Decode(&newTodo)
	if err != nil {
		http.Error(w, fmt.Sprintf("Error decoding todo: %s", err), http.StatusBadRequest)
		return
	}

	t := map[string]interface{}{
		"ID":        fmt.Sprintf("%s", newTodo.ID),
		"Title":   newTodo.Title,
		"Completed": newTodo.Completed,
	}
	todos = append(todos, newTodo)
	err := json.NewEncoder(w).Encode(t)
	if err != nil {
		http.Error(w, fmt.Sprintf("Error encoding todos: %s", err), http.StatusInternalServerError)
	}
}

func updateTodoByID(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	idStr := vars["id"]

	id, err := uuid.Parse(idStr)
	if err != nil {
		http.Error(w, fmt.Sprintf("Invalid ID: %s", err), http.StatusBadRequest)
		return
	}

	var updateTodo Todo
	err = json.NewDecoder(r.Body).Decode(&updateTodo)
	if err != nil {
		http.Error(w, fmt.Sprintf("Error decoding todo: %s", err), http.StatusBadRequest)
		return
	}

	for i, todo := range todos {
		if todo.ID == id {
			todos[i] = updateTodo
			t := map[string]interface{}{
				"ID":        fmt.Sprintf("%s", todo.ID),
				"Title":   todo.Title,
				"Completed": todo.Completed,
			}
			err := json.NewEncoder(w).Encode(t)
			if err != nil {
				http.Error(w, fmt.Sprintf("Error encoding todos: %s", err), http.StatusInternalServerError)
			}
			return
		}
	}

	http.Error(w, "Todo not found", http.StatusNotFound)
}

func deleteTodoByID(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	idStr := vars["id"]

	id, err := uuid.Parse(idStr)
	if err != nil {
		http.Error(w, fmt.Sprintf("Invalid ID: %s", err), http.StatusBadRequest)
		return
	}

	for i, todo := range todos {
		if todo.ID == id {
			todos = append(todos[:i], todos[i+1:]...)
			http.Error(w, "Todo deleted", http.StatusNoContent)
			return
		}
	}

	http.Error(w, "Todo not found", http.StatusNotFound)
}

func main() {
	http.HandleFunc("/todos", listTodos)
	http.HandleFunc("/todos/:id", getTodoByID)
	http.HandleFunc("/todos", createTodo)
	http.HandleFunc("/todos/:id", updateTodoByID)
	http.HandleFunc("/todos/:id", deleteTodoByID)

	log.Fatal(http.ListenAndServe(":8080", nil))
}

