package data

import (
	"fmt"
	"net/http"

	"github.com/gin-gonic/gin"
)

const (
	TodosPath = "/todos"
	TodoID    = ":id"
)

func BindTodo(c *gin.Context) (*Todo, error){
	var todo Todo
	err := c.ShouldBindJSON(&todo)
	if err != nil {
		return nil, fmt.Errorf("invalid json: %w", err)
	}
	return &todo, nil
}

func (d *Data) Todos(c *gin.Context) {
	todos := []Todo{*d.Todo}
	c.JSON(http.StatusOK, todos)
}

func (d *Data) Todo(c *gin.Context) {
	var todo Todo
	id := c.Param(TodoID)
	err := d.DB.First(&todo, id).Error
	if err != nil {
		if err.Error() == "record not found" {
			err = fmt.Errorf("todo not found")
		}
		return gin.Error(err)
	}
	c.JSON(http.StatusOK, todo)
}

func (d *Data) CreateTodo(c *gin.Context) {
	t := new(Todo)
	if err := c.ShouldBindJSON(t); err != nil {
		return gin.Error(err)
	}
	err = d.DB.Create(t).Error
	if err != nil {
		return gin.Error(err)
	}
	c.JSON(http.StatusCreated, t)
}

func (d *Data) UpdateTodo(c *gin.Context) {
	id := c.Param(TodoID)
	t, err := BindTodo(c)
	if err != nil {
		return gin.Error(err)
	}
	err = d.DB.Model(&Todo{ID: id}).Updates(t).Error
	if err != nil {
		return gin.Error(err)
	}
	c.JSON(http.StatusOK, t)
}

func (d *Data) DeleteTodo(c *gin.Context) {
	id := c.Param(TodoID)
	err := d.DB.Delete(&Todo{ID: id}).Error
	if err != nil {
		return gin.Error(err)
	}
	c.JSON(http.StatusOK, gin.H{})
}

