func TestCreateTodo(t *testing.T) {
	testCases := []struct {
		name          string
		todo         Todo
		expectedStatus http.Status
		expectedBody string
	}{
		{
			name:      "valid todo",
			todo:     Todo{ID: uuid.New(), Title: "Test Todo", Completed: false},
			expectedStatus: http.StatusCreated,
			expectedBody: `{"id":"` + testTodo.ID.String() + `","title":"Test Todo","completed":false}`,

		{
			name:      "invalid todo",
			todo:     Todo{ID: uuid.New(), Title: "", Completed: false},
			expectedStatus: http.StatusBadRequest,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			w := httptest.NewRecorder()
