package repository

import (
	"database/sql"
	"errors"

	"github.com/go-kit/kit/log"
)

type Todo struct {
	ID          int    `db:"id"`
	Title       string `db:"title"`
	Completed   bool   `db:"completed"`
}

type TodoRepository interface {
	ListTodos() ([]Todo, error)
	GetTodoByID(id int) (Todo, error)
	CreateTodo(todo Todo) (int, error)
	UpdateTodoByID(id int, title string, completed bool) error
	DeleteTodoByID(id int) error
}

type todoRepository struct {
	db *sql.DB
	log log.Logger
}

func NewTodoRepository(db *sql.DB, logger log.Logger) *todoRepository {
	return &todoRepository{
		db:  db,
		log: logger,
	}
}

func (tr *todoRepository) ListTodos() ([]Todo, error) {
	rows, err := tr.db.Query("SELECT id, title, completed FROM todos")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed)
		if err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return todos, nil
}

func (tr *todoRepository) GetTodoByID(id int) (Todo, error) {
	var todo Todo
	err := tr.db.Get(&todo, "SELECT id, title, completed FROM todos WHERE id=?", id)
	if err != nil {
		return todo, errors.New("todo not found")
	}
	return todo, nil
}

func (tr *todoRepository) CreateTodo(todo Todo) (int, error) {
	result, err := tr.db.Exec("INSERT INTO todos (title, completed) VALUES ($1, $2)", todo.Title, todo.Completed)
	if err != nil {
		return 0, err
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, err
	}
	return int(id), nil
}

func (tr *todoRepository) UpdateTodoByID(id int, title string, completed bool) error {
	_, err := tr.db.Exec("UPDATE todos SET title=$1, completed=$2 WHERE id=$3", title, completed, id)
	if err != nil {
		return err
	}
	return nil
}

func (tr *todoRepository) DeleteTodoByID(id int) error {
	_, err := tr.db.Exec("DELETE FROM todos WHERE id=$1", id)
	if err != nil {
		return err
	}
	return nil
}

