	"compress/gzip"
	"context"
	"io/ioutil"
	"net/http"
	"strings"

	"github.com/go-kit/kit/log"
	httptransport "github.com/go-kit/kit/transport/http"
	"github.com/gorilla/mux"
	"github.com/pkg/errors"
)

func MakeHTTPHandler(endpoints Endpoints, logger log.Logger) http.Handler {
	r := mux.NewRouter()
	r.Use(gzipMiddleware)

	// List todos
	r.Methods("GET").Path("/todos").Handler(
		httptransport.NewServer(endpoints.ListTodosEndpoint, decodeListTodosRequest, encodeResponse, errorEncoder, logger),
	)

	// Get todo by ID
	r.Methods("GET").Path("/todos/{id}").Handler(
		httptransport.NewServer(endpoints.GetTodoByIDEndpoint, decodeGetTodoByIDRequest, encodeResponse, errorEncoder, logger),
	)

	// Create a todo
	r.Methods("POST").Path("/todos").Handler(
		httptransport.NewServer(endpoints.CreateTodoEndpoint, decodeCreateTodoRequest, encodeResponse, errorEncoder, logger),
	)

	// Update todo by ID
	r.Methods("PUT").Path("/todos/{id}").Handler(
		httptransport.NewServer(endpoints.UpdateTodoByIDEndpoint, decodeUpdateTodoByIDRequest, encodeResponse, errorEncoder, logger),
	)

	// Delete todo by ID
	r.Methods("DELETE").Path("/todos/{id}").Handler(
		httptransport.NewServer(endpoints.DeleteTodoByIDEndpoint, decodeDeleteTodoByIDRequest, encodeResponse, errorEncoder, logger),
	)

	return r
}

func decodeListTodosRequest(_ context.Context, r *http.Request) (interface{}, error) {
	return nil, nil
}

func decodeGetTodoByIDRequest(_ context.Context, r *http.Request) (interface{}, error) {
	id, err := strconv.Atoi(mux.Vars(r)["id"])
	if err != nil {
		return nil, errors.Errorf("invalid id: %v", err)
	}
	return id, nil
}

func decodeCreateTodoRequest(_ context.Context, r *http.Request) (interface{}, error) {
	var todo Todo
	err := json.NewDecoder(r.Body).Decode(&todo)
	if err != nil {
		return nil, errors.Errorf("invalid request: %v", err)
	}
	return todo, nil
}

func decodeUpdateTodoByIDRequest(_ context.Context, r *http.Request) (interface{}, error) {
	id, err := strconv.Atoi(mux.Vars(r)["id"])
	if err != nil {
		return nil, errors.Errorf("invalid id: %v", err)
	}
	todo := Todo{}
	err = json.NewDecoder(r.Body).Decode(&todo)
	if err != nil {
		return nil, errors.Errorf("invalid request: %v", err)
	}
	todo.ID = id
	return todo, nil
}

func decodeDeleteTodoByIDRequest(_ context.Context, r *http.Request) (interface{}, error) {
	id, err := strconv.Atoi(mux.Vars(r)["id"])
	if err != nil {
		return nil, errors.Errorf("invalid id: %v", err)
	}
	return id, nil
}

func encodeResponse(ctx context.Context, w http.ResponseWriter, response interface{}) error {
	return json.NewEncoder(w).Encode(response)
}

func errorEncoder(_ context.Context, err error, w http.ResponseWriter) {
	w.WriteHeader(http.StatusInternalServerError)
	json.NewEncoder(w).Encode(map[string]interface{}{"error": err.Error()})
}

func gzipMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if shouldGzip(r.Header.Get("Accept-Encoding")) {
			gz := gzip.NewWriter(w)
			defer gz.Close()

			w.Header().Set("Content-Encoding", "gzip")
			next.ServeHTTP(gz, r)
		} else {
			next.ServeHTTP(w, r)
		}
	})
}

func shouldGzip(accept string) bool {
	for _, token := range strings.Split(accept, ",") {
		if token == "gzip" {
			return true
		}
	}
	return false
}

