package models

import (
    "database/sql"
)

type Todo struct {
    ID      int       `json:"id"`
    Title   string    `json:"title"`
    Completed bool      `json:"completed"`
}

type TodoUpdate struct {
    Title   *string `json:"title,omitempty"`
    Completed *bool   `json:"completed,omitempty"`
}

var db *sql.DB

func init() {
    // Initialize your database connection here
}

func GetAllTodos() []Todo {
    var todos []Todo
    rows, err := db.Query("SELECT id, title, completed FROM todos")
    if err != nil {
        return todos
    }
    defer rows.Close()
    for rows.Next() {
        var todo Todo
        err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed)
        if err != nil {
            continue
        }
        todos = append(todos, todo)
    }
    return todos
}

func GetTodo(id int) (Todo, error) {
    var todo Todo
    err := db.QueryRow("SELECT id, title, completed FROM todos WHERE id = ?", id).Scan(&todo.ID, &todo.Title, &todo.Completed)
    if err != nil {
        return Todo{}, err
    }
    return todo, nil
}

func CreateTodo(todo Todo) {
    db.Exec("INSERT INTO todos (title, completed) VALUES (?, ?)", todo.Title, todo.Completed)
}

func UpdateTodo(id int, updates TodoUpdate) error {
    setFields := []string{}
    args := []interface{}{}

    if updates.Title != nil {
        setFields = append(setFields, "title = ?")
        args = append(args, *updates.Title)
    }

    if updates.Completed != nil {
        setFields = append(setFields, "completed = ?")
        args = append(args, *updates.Completed)
    }

    if len(setFields) == 0 {
        return nil
    }

    query := "UPDATE todos SET " + strings.Join(setFields, ", ") + " WHERE id = ?"
    args = append(args, id)

    _, err := db.Exec(query, args...)
    return err
}

func DeleteTodo(id int) error {
    _, err := db.Exec("DELETE FROM todos WHERE id = ?", id)
    return err
}

