package todos

type TodoController struct {
    service *TodoService
}

func (c *TodoController) List(w http.ResponseWriter, r *http.Request) {
    todos, err := c.service.List()
    if err != nil {
        respondWithError(w, http.StatusInternalServerError, "Could not list todos")
        return
    }
    respondWithJSON(w, http.StatusOK, todos)
}

func (c *TodoController) Get(w http.ResponseWriter, r *http.Request) {
    id, err := strconv.Atoi(r.URL.Query().Get("id"))
    if err != nil {
        respondWithError(w, http.StatusBadRequest, "Invalid todo id")
        return
    }
    todo, err := c.service.Get(id)
    if err != nil {
        respondWithError(w, http.StatusNotFound, "Todo not found")
        return
    }
    respondWithJSON(w, http.StatusOK, todo)
}

func (c *TodoController) Create(w http.ResponseWriter, r *http.Request) {
    var todo Todo
    err := json.NewDecoder(r.Body).Decode(&todo)
    if err != nil {
        respondWithError(w, http.StatusBadRequest, "Could not decode request body")
        return
    }
    id, err := c.service.Create(&todo)
    if err != nil {
        respondWithError(w, http.StatusInternalServerError, "Could not create todo")
        return
    }
    todo.ID = id
    respondWithJSON(w, http.StatusCreated, todo)
}

func (c *TodoController) Update(w http.ResponseWriter, r *http.Request) {
    id, err := strconv.Atoi(r.URL.Query().Get("id"))
    if err != nil {
        respondWithError(w, http.StatusBadRequest, "Invalid todo id")
        return
    }
    var update Todo
    err = json.NewDecoder(r.Body).Decode(&update)
    if err != nil {
        respondWithError(w, http.StatusBadRequest, "Could not decode request body")
        return
    }
    if update.Title == "" && !update.Completed {
        respondWithError(w, http.StatusBadRequest, "No attributes to update")
        return
    }
    err = c.service.Update(id, &update)
    if err != nil {
        respondWithError(w, http.StatusInternalServerError, "Could not update todo")
        return
    }
    todo, err := c.service.Get(id)
    if err != nil {
        respondWithError(w, http.StatusInternalServerError, "Could not get updated todo")
        return
    }
    respondWithJSON(w, http.StatusOK, todo)
}

func (c *TodoController) Delete(w http.ResponseWriter, r *http.Request) {
    id, err := strconv.Atoi(r.URL.Query().Get("id"))
    if err != nil {
        respondWithError(w, http.StatusBadRequest, "Invalid todo id")
        return
    }
    err = c.service.Delete(id)
    if err != nil {
        respondWithError(w, http.StatusInternalServerError, "Could not delete todo")
        return
    }
    w.WriteHeader(http.StatusNoContent)
}

