package todos

import (
    "database/sql"
    "log"
)

type SQLTodoRepository struct {
    db *sql.DB
}

func NewSQLTodoRepository(db *sql.DB) *SQLTodoRepository {
    return &SQLTodoRepository{db: db}
}

func (sr *SQLTodoRepository) List() ([]Todo, error) {
    rows, err := sr.db.Query("SELECT id, title, completed FROM todos")
    if err != nil {
        return nil, err
    }
    var todos []Todo
    for rows.Next() {
        var todo Todo
        if err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed); err != nil {
            return nil, err
        }
        todos = append(todos, todo)
    }
    if err := rows.Err(); err != nil {
        return nil, err
    }
    return todos, nil
}

func (sr *SQLTodoRepository) Get(id int) (*Todo, error) {
    var todo Todo
    err := sr.db.QueryRow("SELECT id, title, completed FROM todos WHERE id = ?", id).Scan(&todo.ID, &todo.Title, &todo.Completed)
    if err == sql.ErrNoRows {
        return nil, nil
    }
    if err != nil {
        log.Println(err)
        return nil, sql.ErrNoRows
    }
    return &todo, nil
}

func (sr *SQLTodoRepository) Create(todo *Todo) (int, error) {
    result, err := sr.db.Exec("INSERT INTO todos (title, completed) VALUES (?, ?)", todo.Title, todo.Completed)
    if err != nil {
        return 0, err
    }
    id, err := result.LastInsertId()
    if err != nil {
        return 0, err
    }
    return int(id), nil
}

func (sr *SQLTodoRepository) Update(id int, todo *Todo) error {
    _, err := sr.db.Exec("UPDATE todos SET title = ?, completed = ? WHERE id = ?", todo.Title, todo.Completed, id)
    return err
}

func (sr *SQLTodoRepository) Delete(id int) error {
    _, err := sr.db.Exec("DELETE FROM todos WHERE id = ?", id)
    return err
}

