package models

import (
	"sync"
)

type Todo struct {
	ID        int    `json:"id"`
	Title     string `json:"title"`
	Completed bool   `json:"completed"`
}

var (
	todos  = make(map[int]Todo)
	nextID = 1
	mu     sync.Mutex
)

func GetTodos() []Todo {
	mu.Lock()
	defer mu.Unlock()

	var allTodos []Todo
	for _, todo := range todos {
		allTodos = append(allTodos, todo)
	}
	return allTodos
}

func CreateTodo(title string, completed bool) *Todo {
	mu.Lock()
	defer mu.Unlock()

	todo := &Todo{
		ID:        nextID,
		Title:     title,
		Completed: completed,
	}
	todos[nextID] = *todo
	nextID++
	return todo
}

func GetTodoByID(id int) *Todo {
	mu.Lock()
	defer mu.Unlock()

	return todos[id]
}

func (t *Todo) Update(title string, completed bool) {
	if title != "" {
		t.Title = title
	}
	if completed {
		t.Completed = completed
	}
}

func DeleteTodo(id int) {
	mu.Lock()
	defer mu.Unlock()

	delete(todos, id)
}

