	id, err := strconv.Atoi(r.URL.Path[1:])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	var updatedTodo Todo
	if err := json.NewDecoder(r.Body).Decode(&updatedTodo); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	// Apply only the attributes present in the body
	if updatedTodo.Title != "" {
		todos[id].Title = updatedTodo.Title
	}
	if updatedTodo.Completed != false {
		todos[id].Completed = updatedTodo.Completed
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todos[id])
}

