	"github.com/gorilla/mux"
)

// Todo represents a todo item with a title and completed status
type Todo struct {
	ID       int      `json:"id"`
	Title    string   `json:"title"`
	Completed bool    `json:"completed"`
}

// TodoList is a slice of Todo items
type TodoList []Todo

// TodoHandler handles all CRUD operations for todos
type TodoHandler struct {
	todos TodoList
}

// NewTodoHandler creates a new TodoHandler
func NewTodoHandler() *TodoHandler {
	return &TodoHandler{
		todos: make(TodoList, 0),
	}
}

// List returns a list of todos
func (h *TodoHandler) List(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(h.todos)
}

// Get retrieves a todo by ID
func (h *TodoHandler) Get(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id, err := strconv.Atoi(vars["id"])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	for _, todo := range h.todos {
		if todo.ID == id {
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(todo)
			return
		}
	}

	http.Error(w, "Todo not found", http.StatusNotFound)
}

// Create creates a new todo
func (h *TodoHandler) Create(w http.ResponseWriter, r *http.Request) {
	var todo Todo
	if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if todo.Title == "" {
		http.Error(w, "Title is required", http.StatusBadRequest)
		return
	}

	todo.ID = len(h.todos) + 1
	h.todos = append(h.todos, todo)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

// Update updates a todo by ID
func (h *TodoHandler) Update(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id, err := strconv.Atoi(vars["id"])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	var todo Todo
	if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	// Update only the fields present in the request body
	for i, todoItem := range h.todos {
		if todoItem.ID == id {
			h.todos[i].Title = todo.Title
			h.todos[i].Completed = todo.Completed
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(h.todos[i])
			return
		}
	}

	http.Error(w, "Todo not found", http.StatusNotFound)
}

// Delete deletes a todo by ID
func (h *TodoHandler) Delete(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id, err := strconv.Atoi(vars["id"])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	for i, todo := range h.todos {
		if todo.ID == id {
			h.todos = append(h.todos[:i], h.todos[i+1:]...)
			w.WriteHeader(http.StatusOK)
			return
		}
	}

	http.Error(w, "Todo not found", http.StatusNotFound)
}

// Router sets up the router for todo API
func (h *TodoHandler) Router() *mux.Router {
	r := mux.NewRouter()

	// GET /todos - list all todos
	r.HandleFunc("/todos", h.List).Methods("GET")

	// GET /todos/{id} - get todo by ID
	r.HandleFunc("/todos/{id}", h.Get).Methods("GET")

	// POST /todos - create a new todo
	r.HandleFunc("/todos", h.Create).Methods("POST")

	// PUT /todos/{id} - update a todo by ID
	r.HandleFunc("/todos/{id}", h.Update).Methods("PUT")

	// DELETE /todos/{id} - delete a todo by ID
	r.HandleFunc("/todos/{id}", h.Delete).Methods("DELETE")

	return r
}

