// Todo represents a todo item with a title and completed status
type Todo struct {
	ID       int      `json:"id"`
	Title    string   `json:"title"`
	Completed bool    `json:"completed"`
}

// TodoList represents a list of todos
type TodoList []Todo

// TodoHandler handles HTTP requests for todo resources
type TodoHandler struct {
	todos TodoList
}

// NewTodoHandler creates a new TodoHandler
func NewTodoHandler() *TodoHandler {
	return &TodoHandler{
		todos: make(TodoList, 0),
	}
}

// List returns a list of todos
func (h *TodoHandler) List(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(h.todos)
}

// GetByID returns a todo by ID
func (h *TodoHandler) GetByID(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Query().Get("id")
	if idStr == "" {
		http.Error(w, "ID is required", http.StatusBadRequest)
		return
	}

	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID format", http.StatusBadRequest)
		return
	}

	todo := findTodoByID(h.todos, id)
	if todo == nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

// Create adds a new todo
func (h *TodoHandler} Create(w http.ResponseWriter, r *http.Request) {
	var todo Todo
	if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if todo.Title == "" {
		http.Error(w, "Title is required", http.StatusBadRequest)
		return
	}

	todo.ID = len(h.todos) + 1
	h.todos = append(h.todos, todo)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

// UpdateByID updates a todo by ID
func (h *TodoHandler) UpdateByID(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Query().Get("id")
	if idStr == "" {
		http.Error(w, "ID is required", http.StatusBadRequest)
		return
	}

	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID format", http.StatusBadRequest)
		return
	}

	var todo Todo
	if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	todo.ID = id
	todoUpdated := false
	for i, t := range h.todos {
		if t.ID == id {
			h.todos[i] = todo
			todoUpdated = true
			break
		}
	}

	if !todoUpdated {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

// DeleteByID deletes a todo by ID
func (h *TodoHandler) DeleteByID(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Query().Get("id")
	if idStr == "" {
		http.Error(w, "ID is required", http.StatusBadRequest)
		return
	}

	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID format", http.StatusBadRequest)
		return
	}

	var found bool
	for i, todo := range h.todos {
		if todo.ID == id {
			h.todos = append(h.todos[:i], h.todos[i+1:]...)
			found = true
			break
		}
	}

	if !found {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	w.WriteHeader(http.StatusNoContent)
}

// findTodoByID finds a todo by ID
func findTodoByID(todos TodoList, id int) *Todo {
	for _, todo := range todos {
		if todo.ID == id {
			return &todo
		}
	}
	return nil
}

