	"log"
	"net/http"
	"strconv"
	"strings"
)

type Todo struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Completed bool  `json:"completed"`
}

var todos = make(map[int]Todo)

func listTodos(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todos)
}

func getTodo(w http.ResponseWriter, r *http.Request) {
	todoID := extractTodoID(r)
	if todoID <= 0 {
		http.Error(w, "Invalid todo ID", http.StatusBadRequest)
		return
	}
	todo, exists := todos[todoID]
	if !exists {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

func createTodo(w http.ResponseWriter, r *http.Request) {
	var newTodo Todo
	if err := json.NewDecoder(r.Body).Decode(&newTodo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if newTodo.Title == "" {
		http.Error(w, "Title is required", http.StatusBadRequest)
		return
	}

	todoID := len(todos) + 1
	newTodo.ID = todoID
	todos[todoID] = newTodo

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(newTodo)
}

func updateTodo(w http.ResponseWriter, r *http.Request) {
	todoID := extractTodoID(r)
	if todoID <=  0 {
		http.Error(w, "Invalid todo ID", http.StatusBadRequest)
		return
	}

	var updatedTodo Todo
	if err := json.NewDecoder(r.Body).Decode(&updatedTodo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if updatedTodo.Title == "" {
		http.Error(w, "Title is required", http.StatusBadRequest)
		return
	}

	updatedTodo.ID = todoID
	todos[todoID] = updatedTodo

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(updatedTodo)
}

func deleteTodo(w http.ResponseWriter, r *http.Request) {
	todoID := extractTodoID(r)
	if todoID <= 0 {
		http.Error(w, "Invalid todo ID", http.StatusBadRequest)
		return
	}

	delete(todos, todoID)

	w.WriteHeader(http.StatusNoContent)
}

func extractTodoID(r *http.Request) int {
	parts := strings.Split(r.URL.Path, "/")
	if len(parts) < 3 {
		return 0
	}
	idStr := parts[2]
	if id, err := strconv.Atoi(idStr); err == nil {
		return id
	}
	return 0
}

func main() {
	http.HandleFunc("/todos", listTodos)
	http.HandleFunc("/todos/", getTodo)
	http.HandleFunc("/todos/create", createTodo)
	http.HandleFunc("/todos/update", updateTodo)
	http.HandleFunc("/todos/delete", deleteTodo)

	log.Println("Server started on :8080")
	http.ListenAndServe(":8080", nil)
}

