	if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	// Find the todo to update
	var found bool
	for i, t := range h.todos {
		if t.ID == id {
			h.todos[i] = todo
			found = true
			break
		}
	}

	if !found {
