)

// Todo represents a todo item with a title and completed status
type Todo struct {
	ID       int      `json:"id"`
	Title    string   `json:"title"`
	Completed bool    `json:"completed"`
}

// TodoList represents a list of todos
type TodoList []Todo

// TodoHandler handles HTTP requests for todo resources
type TodoHandler struct {
	todos TodoList
}

// NewTodoHandler creates a new TodoHandler
func NewTodoHandler() *TodoHandler {
	return &TodoHandler{
		todos: make(TodoList, 0),
	}
}

// List returns a list of todos
func (h *TodoHandler) List(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(h.todos)
}

// Get retrieves a todo by ID
func (h *TodoHandler) Get(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id, err := strconv.Atoi(vars["id"])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	todo := findTodoByID(h.todos, id)
	if todo == nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

// Create adds a new todo
func (h *TodoHandler) Create(w http.ResponseWriter, r *http.Request) {
	var todo Todo
	if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if todo.Title == "" {
		http.Error(w, "Title is required", http.StatusBadRequest)
		return
	}

	todo.ID = len(h.todos) + 1
	h.todos = append(h.todos, todo)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

// Update updates a todo by ID
func (h *TodoHandler) Update(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id, err := strconv.Atoi(vars["id"])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	todo := findTodoByID(h.todos, id)
	if todo == nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	var updatedTodo Todo
	if err := json.NewDecoder(r.Body).Decode(&updatedTodo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	// Apply only the attributes present in the body
	if updatedTodo.Title != "" {
		todo.Title = updatedTodo.Title
	}
	if updatedTodo.Completed != false {
		todo.Completed = updatedTodo.Completed
	}

	h.todos = updateTodoByID(h.todos, id, todo)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

// Delete removes a todo by ID
func (h *TodoHandler) Delete(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id, err := strconv.Atoi(vars["id"])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	todo := findTodoByID(h.todos, id)
	if todo == nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	h.todos = removeTodoByID(h.todos, id)

	w.WriteHeader(http.StatusNoContent)
}

// findTodoByID finds a todo by ID
func findTodoByID(todos TodoList, id int) *Todo {
	for _, todo := range todos {
		if todo.ID == id {
			return &todo
		}
	}
	return nil
}

// updateTodoByID updates a todo by ID
func updateTodoByID(todos TodoList, id int, todo Todo) TodoList {
	var updatedTodos TodoList
	for _, t := range todos {
		if t.ID == id {
			updatedTodos = append(updatedTodos, todo)
		} else {
			updatedTodos = append(updatedTodos, t)
		}
	}
	return updatedTodos
}

// removeTodoByID removes a todo by ID
func removeTodoByID(todos TodoList, id int) TodoList {
	var remainingTodos TodoList
	for _, todo := range todos {
		if todo.ID != id {
			remainingTodos = append(remainingTodos, todo)
		}
	}
	return remainingTodos
}

