func ListTodos(w http.ResponseWriter, r *http.Request) {
	todos := getAllTodos()
	json.NewEncoder(w).Encode(todos)
}

// Handler for GET /todos/{id} - get todo by id
func GetTodo(w http.ResponseWriter, r *http.Request) {
	id := extractID(r)
	if id <= 0 {
		http.Error(w, "Invalid todo ID", http.StatusBadRequest)
		return
	}
	todo := getTodoByID(id)
	if todo == nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}
	json.NewEncoder(w).Encode(todo)
}

// Handler for POST /todos - create a new todo
func CreateTodo(w http.ResponseWriter, r *http.Request) {
	var newTodo Todo
	if err := json.NewDecoder(r.Body).Decode(&newTodo); err != nil {
		http.Error(w, "Invalid JSON or empty body", http.StatusBadRequest)
		return
	}

	if newTodo.Title == "" {
		http.Error(w, "Title is required", http.StatusBadRequest)
		return
	}

	todo := Todo{
		ID:       getNextID(),
		Title:    newTodo.Title,
		Completed: newTodo.Completed,
	}

	saveTodo(todo)
	json.NewEncoder(w).Encode(todo)
}

// Handler for PUT /todos/{id} - update todo by id
func UpdateTodo(w http.ResponseWriter, r *http.Request) {
	id := extractID(r)
	if id <= 0 {
		http.Error(w, "Invalid todo ID", http.StatusBadRequest)
		return
	}

	var updatedTodo Todo
	if err := json.NewDecoder(r.Body).Decode(&updatedTodo); err != nil {
		http.Error(w, "Invalid JSON or empty body", http.StatusBadRequest)
		return
	}

	// Only update fields provided in the request body
	todo := getTodoByID(id)
	if todo == nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	if updatedTodo.Title != "" {
		todo.Title = updatedTodo.Title
	}
	if updatedTodo.Completed != false {
		todo.Completed = updatedTodo.Completed
	}

	saveTodo(todo)
	json.NewEncoder(w).Encode(todo)
}

// Handler for DELETE /todos/{id} - delete todo by id
func DeleteTodo(w http.ResponseWriter, r *http.Request) {
	id := extractID(r)
	if id <= 0 {
		http.Error(w, "Invalid todo ID", http.StatusBadRequest)
		return
	}

	if deleteTodoByID(id) {
		w.WriteHeader(http.StatusOK)
		fmt.Fprint(w, "Todo deleted")
	} else {
		http.Error(w, "Todo not found", http.StatusNotFound)
	}
}

// Helper function to extract ID from URL path
func extractID(r *http.Request) int {
	parts := strings.Split(r.URL.Path, "/")
	if len(parts) < 2 {
		return 0
	}
	id, err := strconv.Atoi(parts[2])
	if err != nil {
		return 0
	}
	return id
}

// Helper function to get all todos
func getAllTodos() TodoList {
	// In a real implementation, this would fetch from a data store
	// For now, just return a placeholder list
	return TodoList{
		{ID: 1, Title: "Learn Go", Completed: false},
		{ID: 2, Title: "Build API", Completed: true},
	}
}

// Helper function to get todo by ID
func getTodoByID(id int) *Todo {
	// In a real implementation, this would fetch from a data store
	// For now, just return a placeholder
	todos := getAllTodos()
	for _, todo := range todos {
		if todo.ID == id {
			return &todo
		}
	}
	return nil
}

