package api

import (
	"encoding/json"
	"net/http"
	"strconv"
	"strings"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
)

// Todo represents a todo item with a title and completed status
type Todo struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Completed bool  `json:"completed"`
}

// TodoList represents a list of todos
type TodoList []Todo

// TodoAPI handles CRUD operations for todos
type TodoAPI struct {
	Store TodoStore
}

// TodoStore defines the interface for todo operations
type TodoStore interface {
	List() TodoList
	Get(id int) (*Todo, error)
	Create(todo Todo) (Todo, error)
	Update(id int, todo Todo) (Todo, error)
	Delete(id int) error
}

// NewTodoAPI creates a new TodoAPI instance
func NewTodoAPI(store TodoStore) *TodoAPI {
	return &TodoAPI{Store: store}
}

// List handles GET /todos
func (a *TodoAPI) List(w http.ResponseWriter, r *http.Request) {
	todos := a.Store.List()
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todos)
}

// Get handles GET /todos/{id}
func (a *TodoAPI) Get(w http.ResponseWriter, r *http.Request) {
	idStr := chi.URLParam(r, "id")
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID format", http.StatusBadRequest)
		return
	}

	todo, err := a.Store.Get(id)
	if err != nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

// Create handles POST /todos
func (a *TodoAPI) Create(w http.ResponseWriter, r *http.Request) {
	var todo Todo
	if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if todo.Title == "" {
		http.Error(w, "Title is required", http.StatusBadRequest)
		return
	}

	newTodo, err := a.Store.Create(todo)
	if err != nil {
		http.Error(w, "Failed to create todo", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(newTodo)
}

// Update handles PUT /todos/{id}
func (a *TodoAPI) Update(w http.ResponseWriter, r *http.Request) {
	idStr := chi.URLParam(r, "id")
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID format", http.StatusBadRequest)
		return
	}

	var todo Todo
	if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	updatedTodo, err := a.Store.Update(id, todo)
	if err != nil {
		http.Error(w, "Failed to update todo", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(updatedTodo)
}

// Delete handles DELETE /todos/{id}
func (a *TodoAPI) Delete(w http.ResponseWriter, r *http.Request) {
	idStr := chi.URLParam(r, "id")
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID format", http.StatusBadRequest)
		return
	}

	err = a.Store.Delete(id)
	if err != nil {
		http.Error(w, "Failed to delete todo", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusNoContent)
}

// Routes returns the Chi router for todo API
func (a *TodoAPI) Routes() chi.Router {
	r := chi.NewRouter()
	r.Use(middleware.Logger)
	r.Use(middleware.Recoverer)

	// Base routes
	r.Get("/todos", a.List)
	r.Get("/todos/{id}", a.Get)
	r.Post("/todos", a.Create)
	r.Put("/todos/{id}", a.Update)
	r.Delete("/todos/{id}", a.Delete)

	return r
}

