)

type Todo struct {
	ID       int      `json:"id"`
	Title    string   `json:"title"`
	Completed bool    `json:"completed"`
}

var todos = map[int]Todo{
	1: {ID: 1, Title: "Learn Go", Completed: false},
	2: {ID: 2, Title: "Build API", Completed: true},
}

// listTodos returns a JSON array of todos
func listTodos(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todos)
}

// getTodo returns a single todo by ID
func getTodo(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.URL.Query().Get("id"))
	if err != nil || id <= 0 {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	todo, exists := todos[id]
	if !exists {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

// createTodo creates a new todo
func createTodo(w http.ResponseWriter, r *http.Request) {
	var newTodo Todo
	if err := json.NewDecoder(r.Body).Decode(&newTodo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if newTodo.Title == "" {
		http.Error(w, "Title is required", http.StatusBadRequest)
		return
	}

	newTodo.ID = len(todos) + 1
	todos[newTodo.ID] = newTodo

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(newTodo)
}

// updateTodo updates an existing todo
func updateTodo(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.URL.Query().Get("id"))
	if err != nil || id <=  0 {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	var updatedTodo Todo
	if err := json.NewDecoder(r.Body).Decode(&updatedTodo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if updatedTodo.Title == "" {
		http.Error(w, "Title is required", http.StatusBadRequest)
		return
	}

	todos[id] = Todo{
		ID:       id,
		Title:    updatedTodo.Title,
		Completed: updatedTodo.Completed,
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todos[id])
}

// deleteTodo deletes a todo by ID
func deleteTodo(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.URL.Query().Get("id"))
	if err != nil || id <= 0 {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	delete(todos, id)
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Todo with ID %d deleted", id)
}

// Handler for all todo-related routes
func TodoHandler() http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			if strings.HasPrefix(r.URL.Path, "/todos") {
				listTodos(w, r)
			} else if strings.HasPrefix(r.URL.Path, "/todos/") {
				getTodo(w, r)
			}
		case http.MethodPost:
			createTodo(w, r)
		case http.MethodPut:
			updateTodo(w, r)
		case http.MethodDelete:
			deleteTodo(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	}
}
